-- 038 — Add 50 language questions
--
-- Pure insert, no passage. Ids are deterministic:
-- One stem, 'Which word is misspelled?', is already used by migration 024,
-- so it is asked here as 'Which word below is misspelled?' — same question,
-- different id, so the new row is not swallowed by ON CONFLICT.
-- md5(section || '|' || prompt)::UUID with ON CONFLICT DO NOTHING, so
-- re-running this file is a no-op. Nothing existing is deleted or updated,
-- and user_question_history is never touched.

WITH q(prompt, options, correct_index, difficulty, explanation) AS (VALUES
  ('Which sentence contains a mistake in capitalization?', '["We celebrate thanksgiving at my grandmother''s house.", "Our new neighbors moved here from Brazil last summer.", "The Mississippi River flows past St. Louis.", "No mistakes"]'::JSONB, 0, 1, 'Holidays are proper nouns and must be capitalized: Thanksgiving. Countries (Brazil) and the names of rivers and cities are already capitalized correctly in the other sentences.'),
  ('Which sentence contains an error in verb agreement?', '["The players on the team practice every afternoon.", "My sister and her friend was late to the concert.", "There are four apples in the bowl.", "No mistakes"]'::JSONB, 1, 1, 'Two subjects joined by ''and'' form a plural subject, so the verb must be ''were late.'' A compound subject always takes a plural verb.'),
  ('Which sentence contains a punctuation error?', '["Yes, I would like another slice.", "We need milk, bread, and eggs.", "Where are you going", "No mistakes"]'::JSONB, 2, 1, 'A direct question must end with a question mark: ''Where are you going?'' The other two sentences are punctuated correctly.'),
  ('Which sentence includes an error?', '["My friends and I rode our bikes to the park.", "The teacher handed out the tests quickly.", "She sings beautiful when she is nervous.", "No mistakes"]'::JSONB, 2, 1, 'An adverb, not an adjective, describes how an action is done: ''She sings beautifully.'' ''Beautiful'' can only describe a noun.'),
  ('Which sentence contains a usage error?', '["Your going to love this movie.", "You''re the fastest runner in our class.", "Your backpack is under the bench.", "No mistakes"]'::JSONB, 0, 1, '''Your'' shows possession; the contraction for ''you are'' is ''you''re.'' The sentence means ''You are going to love this movie.'''),
  ('Which sentence contains an error in word choice?', '["The loud music affected my concentration.", "The new rule had a strong effect on attendance.", "Their new puppy chews everything.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct. ''Affect'' is the verb (the music affected me) and ''effect'' is the noun (it had an effect), and ''their'' is the right possessive pronoun. The answer is ''No mistakes.'''),
  ('Which sentence contains a capitalization error?', '["In September we will study the Civil War.", "My aunt speaks French and Portuguese.", "We drove east on Highway 50 toward the mountains.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct: months and named historical events are capitalized, languages from proper nouns are capitalized, and ''east'' stays lowercase because it names a direction rather than a region. The answer is ''No mistakes.'''),
  ('Which sentence should be corrected?', '["He don''t want to go to the assembly.", "She doesn''t like watching scary movies at night.", "They don''t have practice today.", "No mistakes"]'::JSONB, 0, 1, 'A singular subject like ''he'' takes ''doesn''t'': ''He doesn''t want to go.'' Use ''don''t'' only with I, you, we, and they.'),
  ('Which sentence contains an error in pronoun use?', '["Marcus and I finished the project.", "The prize was shared by Ana and me.", "Him and Tyler built the model.", "No mistakes"]'::JSONB, 2, 1, 'The subject of the sentence needs a subject pronoun: ''He and Tyler built the model.'' Drop the other name to test it — ''Him built the model'' is clearly wrong.'),
  ('Which sentence contains an apostrophe error?', '["The boy''s jacket is on the hook.", "The teachers lounge is down the hall.", "Carla''s brother plays the trumpet.", "No mistakes"]'::JSONB, 1, 1, 'The lounge belongs to the teachers, so the plural possessive is needed: teachers'' lounge, with the apostrophe after the s.'),
  ('Which sentence is not written correctly?', '["We seen the fireworks from the roof.", "We watched the fireworks from the roof.", "We have seen that movie twice.", "No mistakes"]'::JSONB, 0, 1, '''Seen'' is a past participle and needs a helping verb. The simple past of ''see'' is ''saw'': ''We saw the fireworks.'''),
  ('Which sentence contains a mistake in grammar or punctuation?', '["Before the game started, we ate dinner.", "My shoes, which I bought last month, are already worn out.", "The dog barked at the mail carrier.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct: an introductory dependent clause is followed by a comma, a nonessential ''which'' clause is set off by a pair of commas, and the third sentence is a simple correct statement. The answer is ''No mistakes.'''),
  ('Which sentence contains an error in the use of commas?', '["After the movie, we walked home.", "I bought apples, oranges and bananas.", "My best friend Jenna, plays the violin.", "No mistakes"]'::JSONB, 2, 1, 'Never separate a subject from its verb with a single comma: ''My best friend Jenna plays the violin.'' (The comma before the final item in a series is optional, so the second sentence is fine either way.)'),
  ('Which one of these sentences contains an error?', '["The list of names were posted outside the office.", "Several students were waiting outside the office.", "The box of markers is on my desk.", "No mistakes"]'::JSONB, 0, 1, 'The subject is the singular noun ''list,'' not ''names,'' so the verb must be ''was posted.'' A prepositional phrase between subject and verb never changes the verb''s number.'),
  ('Which sentence contains an error in end punctuation?', '["What a great catch that was!", "Please close the door on your way out.", "Did you remember to feed the cat.", "No mistakes"]'::JSONB, 2, 1, 'A sentence that asks something directly ends with a question mark: ''Did you remember to feed the cat?'' A command may end with a period, and an exclamation may end with an exclamation point.'),
  ('Which sentence contains an error in standard usage?', '["I could have finished sooner.", "I should of studied harder.", "We would have called you.", "No mistakes"]'::JSONB, 1, 1, '''Should of'' is a misspelling of the contracted sound of ''should''ve.'' The correct form is ''should have studied harder.'''),
  ('Which sentence contains an error in agreement?', '["Neither of my brothers likes broccoli.", "The team lost its opening game.", "Each of the answers was correct.", "No mistakes"]'::JSONB, 3, 1, 'All three are correct. ''Neither'' and ''each'' are singular pronouns and take singular verbs, and the collective noun ''team'' is treated as a single unit, so it takes the singular pronoun ''its.'' The answer is ''No mistakes.'''),
  ('Which sentence contains an error in quotation punctuation?', JSONB_BUILD_ARRAY('Mrs. Ortiz asked, are we ready to begin?', 'Mrs. Ortiz asked, "Are we ready to begin?"', 'Mrs. Ortiz asked whether we were ready to begin.', 'No mistakes'), 0, 1, 'A direct quotation must be enclosed in quotation marks and begin with a capital letter. The third sentence needs no quotation marks because it reports the question indirectly.'),
  ('Which sentence contains an error in a plural form?', '["The children played in the yard behind the school.", "We saw three deers at the edge of the field.", "She packed two loaves of bread.", "No mistakes"]'::JSONB, 1, 1, '''Deer'' has the same form in the singular and the plural: ''We saw three deer.'' ''Children'' and ''loaves'' are correct irregular plurals.'),
  ('Which sentence has a mistake in it?', '["Our school is much bigger than the one across town.", "This is the best pizza in town.", "Of the two puppies, the beagle is the smallest.", "No mistakes"]'::JSONB, 2, 1, 'Use the comparative form when comparing exactly two things: ''the beagle is the smaller.'' The superlative (''smallest,'' ''best'') is for three or more.'),
  ('Which of these is a sentence fragment rather than a complete sentence?', '["Running through the sprinkler on a hot afternoon.", "The kids ran through the sprinkler.", "It was a hot afternoon.", "Everyone laughed and cheered from the back porch steps."]'::JSONB, 0, 1, 'A complete sentence needs a subject and a verb. ''Running through the sprinkler on a hot afternoon'' has no subject and no main verb — it only describes an action.'),
  ('Which sentence is a run-on sentence?', '["The rain stopped, and the sun came out.", "The rain stopped the sun came out.", "When the rain stopped, the sun came out.", "After the rain, the sun came out."]'::JSONB, 1, 1, 'Two independent clauses are run together with no punctuation and no conjunction. Fix it with a comma plus ''and'' or with a semicolon.'),
  ('Which sentence contains an error in punctuation?', '["The concert, which had been postponed twice, finally took place in June.", "We were told to bring the following: a tent, a sleeping bag, and a flashlight.", "My cousin lives in Portland Oregon and works as a nurse.", "No mistakes"]'::JSONB, 2, 2, 'A city and its state must be separated by a comma: ''Portland, Oregon.'' The first sentence sets off a nonessential clause correctly, and the second uses a colon after a complete independent clause.'),
  ('Which sentence contains an error in wording?', '["The reason for the delay is because the truck broke down.", "The reason for the delay is that the truck broke down.", "The shipment was delayed because the truck broke down.", "No mistakes"]'::JSONB, 0, 3, '''The reason ... is because'' is redundant, since ''reason'' already states the cause. Standard English uses ''the reason ... is that.'''),
  ('Which sentence contains an error in verb tense?', '["When the bell rings, the students rush out, and the hallway fills with noise.", "As soon as the bell rang, the students rushed out, and the hallway fills with noise.", "As soon as the bell rang, the students rushed out, and the hallway filled with noise.", "No mistakes"]'::JSONB, 1, 3, 'The sentence shifts from past (''rang,'' ''rushed'') to present (''fills'') for no reason. Keep the tense consistent: ''the hallway filled with noise.'''),
  ('Which sentence contains an error in subject-verb agreement?', '["Neither the students nor the teacher was aware of the change.", "Either the twins or their mother drives them to practice.", "Not only the coach but also the players was disappointed.", "No mistakes"]'::JSONB, 2, 3, 'With paired conjunctions like ''not only ... but also,'' the verb agrees with the subject closer to it. That subject is the plural ''players,'' so the verb must be ''were disappointed.'''),
  ('Which sentence contains an error in punctuation or usage?', '["The committee announced its decision on Friday.", "She wanted to quickly finish the assignment before dinner.", "We invited three people: my aunt, my cousin, and my neighbor.", "No mistakes"]'::JSONB, 3, 3, 'All three are correct. A collective noun such as ''committee'' takes the singular ''its''; a split infinitive (''to quickly finish'') is not an error in modern usage; and the colon follows a complete independent clause. The answer is ''No mistakes.'''),
  ('Which sentence contains an error in the placement of a modifier?', '["The teacher explained the rule to the students that had been changed.", "The teacher explained to the students the rule that had been changed.", "The rule that had been changed was explained to the students by the teacher.", "No mistakes"]'::JSONB, 0, 3, 'A modifying clause must sit next to the word it describes. As written, ''that had been changed'' appears to describe the students rather than the rule.'),
  ('Which sentence contains an error in the punctuation of a quotation?', JSONB_BUILD_ARRAY('The principal called it "a remarkable achievement."', 'Did the coach really say, "Practice is canceled?"', 'She asked, "When does the bus leave?"', 'No mistakes'), 1, 3, 'The quoted words are a statement; the whole sentence is the question, so the question mark belongs outside the quotation marks: say, "Practice is canceled"? In the third sentence the quoted words themselves are the question, so the mark goes inside.'),
  ('Which sentence contains an error in parallel structure?', '["The job requires patience, creativity, and attention to detail.", "She is responsible for scheduling meetings, ordering supplies, and training new staff.", "The manual explains how to assemble the shelf, how to mount it, and the way you anchor it.", "No mistakes"]'::JSONB, 2, 3, 'Items in a series must share the same grammatical form. Two ''how to'' phrases followed by ''the way you anchor it'' breaks the pattern; it should read ''how to anchor it.'''),
  ('Which sentence contains an error a careful editor would flag?', '["Fewer than twenty students signed up, so the trip was canceled.", "The amount of rain that fell exceeded last year''s total.", "Between the two proposals, hers is the more practical.", "No mistakes"]'::JSONB, 3, 3, 'All three are correct. Use ''fewer'' with things you can count (students) and ''amount'' with things you measure (rain), and use the comparative ''more practical'' when comparing exactly two. The answer is ''No mistakes.'''),
  ('Which sentence contains an error in comparison?', '["The new stadium holds more fans than any stadium in the league.", "The new stadium holds more fans than any other stadium in the league.", "The new stadium is the largest in the league.", "No mistakes"]'::JSONB, 0, 3, 'The new stadium is itself in the league, so as written it must hold more fans than itself. Adding ''other'' excludes it from the group it is being compared with.'),
  ('Which sentence contains an error in the use of a semicolon or colon?', '["The results were clear; the experiment had failed.", "There is only one thing left to do; finish the report.", "Our itinerary includes three cities: Denver, Santa Fe, and Tucson.", "No mistakes"]'::JSONB, 1, 3, 'A semicolon joins two independent clauses, but ''finish the report'' is not a clause that can stand alone here. A colon is required instead.'),
  ('Which word below is misspelled?', '["surprise", "goverment", "attention", "No mistakes"]'::JSONB, 1, 1, 'The correct spelling is ''government'' — it keeps the n from ''govern'' before the ending -ment.'),
  ('Choose the misspelled word.', '["arguement", "grammar", "familiar", "No mistakes"]'::JSONB, 0, 1, 'The correct spelling is ''argument.'' The silent e in ''argue'' is dropped before the ending -ment.'),
  ('Which of these words is spelled incorrectly?', '["knowledge", "restaurant", "athelete", "No mistakes"]'::JSONB, 2, 1, 'The correct spelling is ''athlete'' — two syllables, with no extra e between the h and the l.'),
  ('Which word contains a spelling error?', '["until", "across", "beginning", "No mistakes"]'::JSONB, 3, 1, 'All three are spelled correctly: ''until'' has one l, ''across'' has one c, and ''beginning'' doubles the n before -ing. The answer is ''No mistakes.'''),
  ('One of these words is spelled incorrectly. Which one?', '["forty", "eighth", "ninty", "No mistakes"]'::JSONB, 2, 1, 'The correct spelling is ''ninety,'' which keeps the e from ''nine.'' (Note that ''forty'' drops the u of ''four.'')'),
  ('Which word is misspelled in this group?', '["reccommend", "committee", "definitely", "No mistakes"]'::JSONB, 0, 3, 'The correct spelling is ''recommend'' — one c and two m''s.'),
  ('Select the misspelled word.', '["parallel", "sincerely", "vacuum", "No mistakes"]'::JSONB, 3, 3, 'All three are spelled correctly: ''parallel'' has a double l only in the middle, ''sincerely'' keeps the e of ''sincere,'' and ''vacuum'' has two u''s. The answer is ''No mistakes.'''),
  ('Which of the following words is spelled incorrectly?', '["exaggerate", "posession", "rhyme", "No mistakes"]'::JSONB, 1, 3, 'The correct spelling is ''possession'' — two s''s in the middle and two more before the ending.'),
  ('Which sentence best combines these two sentences? ''The storm knocked down a tree.'' and ''The tree blocked our driveway.''', '["The storm knocked down a tree, it blocked our driveway.", "The storm knocked down a tree that blocked our driveway.", "The storm knocked down a tree, and blocking our driveway.", "The storm knocked down a tree, but it blocked our driveway."]'::JSONB, 1, 1, 'A relative clause folds the second fact into the first smoothly. The first option is a comma splice, the third is ungrammatical, and ''but'' in the fourth wrongly signals a contrast.'),
  ('Which sentence is the clearest and most concise?', '["Due to the fact that she was tired, she went to bed early.", "On account of being tired, an early bedtime was chosen by her.", "Because she was tired, she went to bed early.", "She went to bed early, the reason being that she was tired."]'::JSONB, 2, 1, '''Because'' says in one word what ''due to the fact that,'' ''on account of,'' and ''the reason being that'' take several words to say, and it keeps the subject doing the action.'),
  ('Which sentence best introduces a paragraph about the benefits of reading for pleasure?', '["Students who read for pleasure build stronger vocabularies and focus.", "Last summer I checked out three books from the public library downtown.", "Libraries are usually open on weekends and most weekday evenings.", "Reading is a thing that many different kinds of people enjoy doing."]'::JSONB, 0, 1, 'A topic sentence names the subject and states the point the paragraph will support. The others give a personal detail, an unrelated fact, or a vague statement with no claim to develop.'),
  ('Which transition best completes the sentence? ''The bridge was closed for repairs; ______, drivers had to take the long way around town.''', '["however", "for instance", "nevertheless", "as a result"]'::JSONB, 3, 2, 'The detour is the consequence of the closure, so a cause-and-effect transition is needed. ''However'' and ''nevertheless'' signal contrast, and ''for instance'' introduces an example.'),
  ('Which sentence does NOT belong in this paragraph? (1) Sea otters spend nearly their whole lives in the water. (2) Their thick fur traps air and keeps them warm in cold currents. (3) Kelp is harvested commercially for use in ice cream and toothpaste. (4) Otters often wrap themselves in kelp so they do not drift away while sleeping.', '["Sea otters spend nearly their whole lives in the water.", "Their thick fur traps air and keeps them warm in cold currents.", "Kelp is harvested commercially for use in ice cream and toothpaste.", "Otters often wrap themselves in kelp so they do not drift away while sleeping."]'::JSONB, 2, 2, 'The paragraph is about how sea otters live in the ocean. A fact about the commercial uses of kelp shifts to a different subject and breaks the paragraph''s unity, even though kelp is mentioned again in sentence 4.'),
  ('Sentences 1-4 appear in scrambled order. Which arrangement makes the most logical paragraph? 1. The dough must then rest for an hour so the gluten relaxes. 2. Begin by stirring the flour, water, and yeast together in a large bowl. 3. Once it has doubled in size, punch it down and shape it into a loaf. 4. Knead the mixture until it is smooth and springs back when pressed.', '["2 - 1 - 4 - 3", "2 - 4 - 1 - 3", "4 - 2 - 1 - 3", "2 - 4 - 3 - 1"]'::JSONB, 1, 3, 'Sentence 2 says ''Begin,'' so it comes first; you must knead ''the mixture'' (4) before the dough can rest (1); and ''Once it has doubled in size'' (3) can only follow the resting period.'),
  ('Where does this sentence best fit? ''Even so, the cost of the equipment kept many schools from joining.'' Paragraph: (1) The new robotics league promised to reach students in every district. (2) Organizers waived entry fees and provided free coaching. (3) By spring, only a dozen teams had registered. (4) Next year the league plans to lend kits to any school that asks.', '["Between sentences 2 and 3", "Before sentence 1", "Between sentences 1 and 2", "After sentence 4"]'::JSONB, 0, 3, '''Even so'' must contrast with something already stated — the waived fees and free coaching in sentence 2 — and it explains the low turnout reported in sentence 3, so it belongs between them.'),
  ('Which revision best improves this sentence? ''The report, which was written by the committee, contained recommendations that were made about how the budget should be handled in the future.''', '["The report written by the committee contained recommendations about how the budget should be handled in the future by the district.", "Recommendations about the future handling of the budget were contained in the report that had been written by the committee.", "The committee''s report recommended how to handle the budget in the future.", "The report by the committee had in it recommendations concerning future budget handling."]'::JSONB, 2, 3, 'The strongest revision makes the real actor the subject and the real action the verb: the committee''s report recommended. The other versions keep the weak verbs ''contained'' and ''had in it'' and the passive phrasing.'),
  ('A paragraph argues that cities should build more protected bike lanes. Which sentence best supports that argument with evidence?', '["Many people in the suburbs say they enjoy riding their bicycles on quiet weekend mornings.", "Bike lanes are painted bright green in some downtown neighborhoods.", "Cars and bicycles do not always get along well on crowded city streets.", "Protected bike lanes cut cyclist crashes by nearly forty percent."]'::JSONB, 3, 3, 'Evidence is a specific, measurable fact that backs the claim. The other options offer a personal preference, a descriptive detail, and a vague generalization, none of which shows that bike lanes help.')
)
INSERT INTO questions (id, section, passage, prompt, options, correct_index, difficulty, explanation)
SELECT md5('language' || '|' || q.prompt)::UUID, 'language'::section_type, NULL,
       q.prompt, q.options, q.correct_index, q.difficulty, q.explanation
FROM q
ON CONFLICT (id) DO NOTHING;

-- ── Verification: expect 50 rows ─────────────────────────────────────
SELECT '038 language' AS migration, COUNT(*)::TEXT AS present, '50' AS expected
FROM questions
WHERE id IN (
  md5('language' || '|' || 'Which sentence contains a mistake in capitalization?')::UUID,
  md5('language' || '|' || 'Which sentence contains an error in verb agreement?')::UUID,
  md5('language' || '|' || 'Which sentence contains a punctuation error?')::UUID,
